mod audio;mod game;mod video;use game::Game;
fn main(){let mut captures=vec![];for rotation in (0..256).step_by(4){let mut g=Game::new(false).unwrap();g.memory.fill(0);g.memory[0x23]=rotation as u8;for slot in 0..32{g.memory[0x500+slot]=16;g.memory[0x560+slot]=64;g.memory[0x5a0+slot]=(16+slot*6)as u8;}g.draw_call().unwrap();let entries:Vec<_>=(0..64).filter_map(|slot|{let i=0x200+slot*4;(g.memory[i]!=244).then(||serde_json::json!({"priority":slot,"y":g.memory[i],"tile":g.memory[i+1],"x":g.memory[i+3]}))}).collect();captures.push(serde_json::json!({"before":rotation/4,"after":g.memory[0x23]/4,"entries":entries}));}println!("{}",serde_json::to_string(&captures).unwrap());}
